import {language} from '../i18n.js';
import {escapeHTML as e} from '../explorer-views.js';
import {renderCareerStarMap} from '../star-map.js';
import {renderSkillDna} from './skill-tree.js';
import {buildCareerStudy,futureSkillAxes} from './career-research.js';
import {pick,STATUS,simulate} from './engine.js';
export const L=(en,zh,ms)=>pick([en,zh,ms],language);
const P=x=>pick(x,language);
const label=s=>P(STATUS[s]||STATUS.unknown);
const button=(title,action,cls='button secondary')=>`<button type="button" class="${cls}" data-combined-action="${e(action)}">${e(title)} ↗</button>`;
const header=(n,k,title,sub)=>`<header class="an-head"><span class="an-eyebrow">0${n} / 05 · ${k}</span><h1 tabindex="-1">${title}</h1><p>${sub}</p></header>`;
const sourceLink=s=>s?`<a target="_blank" rel="noopener noreferrer" href="${e(s.url)}">O*NET · ${e(s.id)} ↗</a>`:'';
const REGION_LABEL={MY:['Malaysia','马来西亚','Malaysia'],US:['United States','美国','Amerika Syarikat'],GLOBAL:['International','国际','Antarabangsa']};
const AI_PATH_LABEL={'ai-growth':['AI-driven opportunity & growth','AI 驱动的新机会与增长','Peluang & pertumbuhan dipacu AI'],'automation-pressure':['Higher automation pressure','较高自动化压力','Tekanan automasi lebih tinggi'],restructuring:['Task restructuring','职业任务重组','Penstrukturan semula tugas'],'limited-change':['Limited near-term change','短期变化相对有限','Perubahan jangka pendek terhad']};
const AI_TASK_LABEL={assist:['AI-assisted','AI 辅助','Bantuan AI'],automate:['Automation potential','自动化潜力','Potensi automasi'],human:['Human-led','人类主导','Diterajui manusia'],grow:['AI-driven growth','AI 驱动增长','Pertumbuhan dipacu AI'],context:['Context-dependent','依情境而定','Mengikut konteks']};
function renderAIImpact(r){const imp=r.aiImpact;if(!imp)return '';const by={};for(const item of imp.tasks)(by[item.category]=by[item.category]||[]).push(item);const order=['automate','assist','grow','human','context'];return `<section class="an-ai-impact"><h3>${L('How AI may change this work','AI 如何改变这份工作','Cara AI mengubah kerja ini')}</h3><p class="an-ai-path"><strong>${e(L(...(AI_PATH_LABEL[imp.path]||AI_PATH_LABEL.restructuring)))}</strong></p><ul>${order.filter(category=>by[category]?.length).map(category=>`<li><span class="an-ai-cat">${e(L(...AI_TASK_LABEL[category]))}</span>${by[category].map(item=>`<span lang="en">${e(item.label)}</span>`).join('')}</li>`).join('')}</ul><p class="an-ai-note">${L('A task-level planning heuristic, not a job-disappearance probability or an official automation forecast.','这是任务层面的规划启发式，不是岗位消失概率或官方自动化预测。','Heuristik perancangan peringkat tugas, bukan kebarangkalian hilang pekerjaan atau ramalan automasi rasmi.')}</p></section>`;}
function renderCareerStudy(a,r){const study=buildCareerStudy(a,r);if(!study)return '';const taskOrder=['core','aiChanged','creative','human','auxiliary'];const taskLabels={core:['Core professional tasks','核心专业任务','Tugas profesional teras'],aiChanged:['Tasks AI may change','AI 可能改变的任务','Tugas yang mungkin diubah AI'],creative:['Creative / generative tasks','创造与生成任务','Tugas kreatif / generatif'],human:['Judgment & collaboration','判断与协作','Pertimbangan & kerjasama'],auxiliary:['Routine support tasks','重复性辅助任务','Tugas sokongan rutin']};const skillLabels={technical:['Technical & digital','技术与数字','Teknikal & digital'],people:['People & coordination','人际与协调','Orang & koordinasi'],cognitive:['General cognitive','通用认知','Kognitif umum']};const shift=study.valueShift;const sourceUrl=study.sourceId?.startsWith('onet:')?`https://www.onetonline.org/link/summary/${encodeURIComponent(study.sourceId.slice(5))}`:'';return `<section class="an-career-study"><div class="an-study-head"><h3>${L('What this work really involves','这份工作究竟在做什么','Apa yang sebenarnya terlibat dalam kerja ini')}</h3>${sourceUrl?`<a target="_blank" rel="noopener noreferrer" href="${e(sourceUrl)}">O*NET · ${e(study.sourceId)} · ${e(study.sourceVersion)} ↗</a>`:''}</div><p class="an-study-desc" lang="en">${e(study.description)}</p><details class="an-study-block" open><summary>${L('Task structure','任务结构','Struktur tugas')}</summary><ul>${taskOrder.filter(k=>study.taskStructure.counts[k]).map(k=>`<li><strong>${e(L(...taskLabels[k]))}</strong> <small>${study.taskStructure.counts[k]}</small>${study.taskStructure.categories[k].slice(0,4).map(t=>`<span lang="en">${e(t.label)}</span>`).join('')}</li>`).join('')}</ul></details><details class="an-study-block"><summary>${L('Skill structure','技能结构','Struktur kemahiran')}</summary><ul>${Object.entries(study.skillGroups).filter(([,v])=>v.length).map(([k,v])=>`<li><strong>${e(L(...skillLabels[k]))}</strong>${v.map(s=>`<span lang="en">${e(s.label)}</span>`).join('')}</li>`).join('')}</ul></details><details class="an-study-block"><summary>${L('How AI may shift the work','AI 如何改变工作重心','Cara AI mengubah tumpuan kerja')}</summary>${shift.rising.length?`<p><strong>${L('Likely more important','可能更重要','Mungkin lebih penting')}</strong> ${shift.rising.map(x=>`<span lang="en">${e(x)}</span>`).join(' · ')}</p>`:''}${shift.declining.length?`<p><strong>${L('May become less central','可能不再那么核心','Mungkin kurang penting')}</strong> ${shift.declining.map(x=>`<span lang="en">${e(x)}</span>`).join(' · ')}</p>`:''}</details><details class="an-study-block"><summary>${L('Related directions','相关方向','Arah berkaitan')}</summary>${study.development.adjacent.length?study.development.adjacent.slice(0,3).map(x=>`<p><strong>${e(P(x.title))}</strong> · ${L('shared skills','共有技能','kemahiran dikongsi')}: ${x.shared.slice(0,3).map(s=>`<span lang="en">${e(s)}</span>`).join(' · ')}</p>`).join(''):`<p>${L('No shared-skill basis recorded for other routes.','未记录与其他路线的共有技能基础。','Tiada asas kemahiran dikongsi untuk laluan lain.')}</p>`}</details><p class="an-study-note">${L('Task and skill groupings are team inference on official O*NET text; official excerpts stay in English. This is occupational context, not a job-outcome prediction.','任务与技能分组是基于 O*NET 官方文本的团队推断；官方原文保留英文。这是职业背景，不是职业结果预测。','Pengelasan tugas dan kemahiran ialah inferens pasukan atas teks rasmi O*NET; petikan rasmi kekal dalam bahasa Inggeris. Ini konteks pekerjaan, bukan ramalan hasil kerja.')}</p></section>`;}
function changesNote(s){const items=[];if((s.changes||[]).includes('default-budget'))items.push(L('A default budget of five hours was applied; change it to see how milestones move.','使用了默认五小时预算；调整后可看到里程碑如何变化。','Bajet lalai lima jam digunakan; ubah untuk melihat perubahan pencapaian.'));if((s.changes||[]).includes('time'))items.push(L('Changing weekly time reschedules milestones only; it does not create skill.','调整每周时间只会重新安排里程碑，不会创造能力。','Mengubah masa mingguan hanya menjadualkan semula pencapaian, bukan mencipta kemahiran.'));if((s.changes||[]).includes('assumed-sample'))items.push(L('Assuming the task sample was reviewed shortens preparation; this is a scenario assumption, not verified evidence.','假设任务样本已复核会缩短准备；这是情景假设，不是已验证证据。','Andaian sampel tugas disemak memendekkan persediaan; ini andaian senario, bukan bukti disahkan.'));if((s.changes||[]).includes('focus'))items.push(L('A focused practice adds one bounded session; the prerequisite order is unchanged.','重点练习会增加一个限定会话；先修顺序不变。','Latihan fokus menambah satu sesi terhad; urutan prasyarat tidak berubah.'));if(!items.length)items.push(L('This is the baseline plan for your reported starting point.','这是基于你自述起点的基础计划。','Ini pelan asas bagi titik permulaan dilaporkan.'));return `<section class="an-whatif-changes"><h3>${L('What this scenario changes','本情景改变了什么','Perubahan senario ini')}</h3><ul>${items.map(x=>`<li>${e(x)}</li>`).join('')}</ul><p>${L('Time creates room for learning; it never proves skill. All milestones remain planned, not completed.','时间提供学习空间，但不能证明能力。所有里程碑仍是计划，不是已完成。','Masa memberi ruang untuk belajar; ia tidak membuktikan kemahiran. Semua pencapaian kekal dirancang, bukan selesai.')}</p></section>`;}
function response(x){if(x==null)return L('Unknown','未知','Tidak diketahui');if(Array.isArray(x))return x.map(response).join(' · ');if(typeof x==='object'){if(x.en)return P(x);return Object.entries(x).map(([k,v])=>`${k}: ${response(v)}`).join(' · ');}return String(x);}
export function evidence(a,ids){const rows=a.evidence.filter(x=>ids.includes(x.id));return `<details class="an-evidence"><summary>${L('See the evidence','查看依据','Lihat bukti')} · ${ids.map(e).join(' / ')}</summary>${rows.map(x=>`<blockquote data-evidence-question="${e(x.id)}"><strong>${e(x.id)} · ${e(P(x.question))}</strong><p>${e(response(x.response))}${Number.isInteger(x.raw)?` · ${x.raw}/7`:''}</p><small>${x.missing?L('Not assessed','未评估','Belum dinilai'):L('Self-report · not independently verified','自述 · 未经独立验证','Laporan kendiri · belum disahkan secara bebas')}</small></blockquote>`).join('')}</details>`;}
function methodology(a){return `<details class="an-method"><summary>${L('How this report was built','报告如何形成','Cara laporan dibina')}</summary><p>${e(P(a.limits))}</p><p>${L('Interest and work preferences use the original seven-point answers. Readiness is reported experience; each occupational skill stays unknown until separately checked. Market context does not change personal task ordering.','兴趣与工作偏好使用原始七点回答。准备度来自自述经历；具体职业技能在单独核验前均为未知。市场背景不改变个人任务排序。','Minat dan keutamaan kerja menggunakan jawapan tujuh mata asal. Kesediaan ialah pengalaman dilaporkan; kemahiran pekerjaan kekal tidak diketahui sehingga disemak. Konteks pasaran tidak mengubah susunan tugas.')}</p><dl><dt>${L('Rules / occupational data','规则／职业数据','Peraturan / data pekerjaan')}</dt><dd>${e(a.version)} · ${e(a.knowledgeVersion)}</dd><dt>${L('Report / generated','报告／生成时间','Laporan / dijana')}</dt><dd>${e(a.id)} · ${e(a.generatedAt||L('Current session','当前会话','Sesi semasa'))}</dd><dt>${L('Missing evidence','缺失证据','Bukti tiada')}</dt><dd>${e(a.missing.join(', ')||'—')}</dd></dl><p>O*NET Database · USDOL/ETA · <a href="https://www.onetcenter.org/license_db.html" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. ${L('Task mappings, translations and learning estimates are team additions, not endorsed by the source. Official excerpts are retained in English.','任务映射、翻译和学习工时估计为团队补充，未经来源机构背书。官方原文保留英文。','Pemetaan tugas, terjemahan dan anggaran pembelajaran ialah tambahan pasukan, bukan disokong sumber. Petikan rasmi dikekalkan dalam bahasa Inggeris.')}</p></details>${renderSourceSnapshot(a)}`;}
const field=(a,id,part)=>{const r=a.evidence.find(x=>x.id===id);return response(part?r?.response?.[part]:r?.response);};
function priority(a){const r=a.roles.find(r=>r.id===a.priority.roleId);const title=a.priority.kind==='verification'?L('Verify one AI-assisted result','核验一项 AI 辅助结果','Sahkan satu hasil bantuan AI'):a.priority.kind==='guided-sample'?L('Build one guided work sample','完成一个有指导的样本','Bina satu sampel berpandu'):L('Document a repeatable AI workflow','记录可重复的 AI 工作流程','Dokumentasikan aliran kerja AI boleh ulang');return `<section class="an-priority"><span class="an-eyebrow">${L('ONE PRIORITY','唯一优先项','SATU KEUTAMAAN')}</span><h2>${title}</h2><p>${e(P(r.project))}</p><p>${a.priority.kind==='verification'?L('Your checking evidence is incomplete or inconsistent. Save the original inputs, one independent check and a corrected output.','核验依据不完整或不一致。请保留原始输入、一次独立核查及修正结果。','Bukti semakan tidak lengkap atau bercampur. Simpan input asal, satu semakan bebas dan hasil dibetulkan.'):L('Use a concrete artifact to test the experience you reported. Record decisions, mistakes and changes; a completed sample is not a professional credential.','用具体作品验证自述经历。记录决策、错误与修改；完成样本不等于职业资格。','Gunakan hasil konkrit untuk menguji pengalaman dilaporkan. Rekod keputusan, ralat dan perubahan; sampel siap bukan kelayakan profesional.')}</p>${evidence(a,a.priority.evidenceIds)}${button(L('Plan this practice','规划这项实践','Rancang latihan ini'),'plan:'+r.id)}</section>`;}
export function profile(model){const a=model.assessment;return `<div class="an-view an-profile" data-rebuild="profile">${header(1,L('YOUR STARTING POINT','你的起点','TITIK PERMULAAN ANDA'),L('A clearer picture<br>of where you are.','看清当下，<br>找到下一步。','Gambaran lebih jelas<br>tentang diri anda.'),L('Your interests, experience and real constraints, read together.','把兴趣、经历和现实条件放在一起理解。','Minat, pengalaman dan kekangan anda, difahami bersama.'))}<p class="an-coverage">${a.evidence.filter(x=>x.dimension!=='context'&&!x.missing).length}/12 · ${L('interpretable direction answers','可解释的方向题回答','jawapan arah boleh ditafsir')}</p><section class="an-story"><div class="an-margin">${L('RIGHT NOW','此刻','SEKARANG')}</div><div><h2>${e(field(a,'Q01'))}</h2><p class="an-lead">${e(field(a,'Q02','primary'))}</p><p>${L('What you want from this report','你希望从报告得到','Harapan anda daripada laporan')}: ${e(field(a,'Q08'))}</p>${evidence(a,['Q01','Q02','Q03','Q08','Q10','Q11'])}</div></section><section class="an-signal-strip">${[['interest',L('Interest','兴趣','Minat')],['experience',L('Experience','经历','Pengalaman')],['ai_verification',L('AI checking','AI 核验','Semakan AI')]].map(([k,t])=>`<div><span>${t}</span><strong>${e(label(a.dimensions[k].status))}</strong></div>`).join('')}</section><section class="an-story"><div class="an-margin">${L('WHAT MATTERS','关键观察','PERKARA PENTING')}</div><div><h2>${L('What could move you forward?','什么能帮助你向前一步？','Apakah yang boleh membantu anda maju?')}</h2>${a.insights.map((i,n)=>`<article class="an-insight"><span>${String(n+1).padStart(2,'0')}</span><div><p>${e(P(i.copy))}</p>${evidence(a,i.evidenceIds)}</div></article>`).join('')}</div></section><section class="an-story"><div class="an-margin">${L('STRENGTH CLUES','优势线索','PETUNJUK KEKUATAN')}</div><div><h2>${L('Separate what you report<br>from what is verified.','分清自述线索<br>与验证过的能力。','Bezakan laporan kendiri<br>daripada bukti disahkan.')}</h2><p>${e(field(a,'Q06'))}</p><p>${e(field(a,'Q05'))}</p><p>${L('No work sample has been independently evaluated here. These are useful starting clues, not verified professional skills.','这里尚未独立评估任何作品。这些是有用的起点线索，不是已验证的专业技能。','Tiada sampel kerja dinilai secara bebas di sini. Ini petunjuk permulaan, bukan kemahiran profesional disahkan.')}</p>${evidence(a,['Q04','Q05','Q06',a.direction+'05',a.direction+'06'])}</div></section>${a.conflicts.length?`<section class="an-tension"><h2>${L('A question worth clarifying','值得澄清的差异','Perkara yang perlu dijelaskan')}</h2>${a.conflicts.map(c=>`<p>${e(P(c.copy))}</p>${evidence(a,c.evidenceIds)}`).join('')}</section>`:''}${priority(a)}${methodology(a)}${button(L('Understand my AI practice','了解我的 AI 实践','Fahami amalan AI saya'),'page:capability')}</div>`;}
const aiTitles={awareness:['AI awareness','AI 认知','Kesedaran AI'],usage:['Practical usage clues','实际使用线索','Petunjuk penggunaan praktikal'],verification:['Verification habits','核验习惯','Amalan pengesahan'],workflow:['Workflow integration','工作流整合','Integrasi aliran kerja'],development:['Development & automation','开发与自动化','Pembangunan dan automasi']};
export function capability(model,options={}){const a=model.assessment;return `<div class="an-view an-capability" data-rebuild="capability">${header(2,L('AI PRACTICE, WITH EVIDENCE','用证据看 AI 实践','AMALAN AI BERBUKTI'),L('Use it.<br>Question it. Build on it.','使用它。核验它。<br>再进一步。','Gunakannya.<br>Semak. Kemudian bina.'),L('Using AI is different from building AI systems. Your answers describe habits and intentions, not a technical certification.','使用 AI 与开发 AI 系统是不同的事。回答描述习惯与意愿，不代表技术认证。','Menggunakan AI berbeza daripada membina sistem AI. Jawapan menerangkan amalan dan niat, bukan pensijilan teknikal.'))}<section class="an-readiness">${a.ai.map((d,i)=>`<article class="an-dimension ${d.status==='unknown'?'is-unknown':''}"><span class="an-dim-index">0${i+1}</span><div><h2>${e(P(aiTitles[d.id]))}</h2><p>${e(label(d.status))}</p>${d.status==='unknown'?`<small>${L('The questionnaire does not establish this capability.','问卷没有确立这项能力。','Soal selidik tidak menentukan kebolehan ini.')}</small>`:evidence(a,d.evidenceIds)}</div><span class="an-status-dot status-${d.status}" aria-hidden="true"></span></article>`).join('')}</section>${a.conflicts.map(c=>`<div class="an-tension"><p>${e(P(c.copy))}</p>${evidence(a,c.evidenceIds)}</div>`).join('')}${priority(a)}<section class="an-story"><div class="an-margin">${L('UNMEASURED','尚未测量','BELUM DIUKUR')}</div><div><h2>${L('What a questionnaire cannot verify','问卷无法验证的部分','Perkara yang tidak boleh disahkan melalui soal selidik')}</h2><p>${L('Python, API integration, model training, agents and deployment need separate work evidence. Interest and reported AI use do not establish these skills.','Python、API 集成、模型训练、智能体和部署需要单独的作品证据。兴趣和 AI 使用自述不能确立这些技能。','Python, integrasi API, latihan model, ejen dan deployment memerlukan bukti kerja berasingan. Minat dan penggunaan AI tidak menentukan kemahiran ini.')}</p></div></section>${aiPanel(options)}${methodology(a)}</div>`;}
function aiPanel(o){return `<section class="an-ai"><h2>${L('An optional AI reading guide','可选的 AI 阅读引导','Panduan bacaan AI pilihan')}</h2><p>${L('Ask AI to select relevant evidence and order your next checks. It cannot add scores, skills or market facts. The full report already works without it.','让 AI 挑选相关证据并安排下一步核查顺序。它不能添加分数、技能或市场事实。完整报告无需 AI 也可使用。','Minta AI memilih bukti berkaitan dan menyusun semakan seterusnya. Ia tidak boleh menambah skor, kemahiran atau fakta pasaran. Laporan lengkap sudah boleh digunakan tanpa AI.')}</p><label class="an-consent"><input type="checkbox" data-assessment-consent ${o.aiConsent?'checked':''}> ${L('Send my twelve direction answers to RunPod for this request. My free text and starting questionnaire stay in the browser.','同意本次向 RunPod 发送十二道方向题回答。自由文本与起点问卷留在浏览器。','Hantar dua belas jawapan arah saya ke RunPod untuk permintaan ini. Teks bebas dan soal selidik permulaan kekal dalam pelayar.')}</label>${button(L('Request AI guide','请求 AI 引导','Minta panduan AI'),'assessment-ai')}${o.ai?.status==='loading'?`<p role="status">${L('Preparing the guide… You can keep exploring.','正在准备引导…你可以继续浏览。','Menyediakan panduan… Anda boleh terus meneroka.')}</p>`:''}${o.ai?.status==='error'?`<p role="status">${e(o.ai.message)}</p>`:''}${o.ai?.status==='complete'?`<ol>${(o.ai.result.guide||[]).map(x=>`<li>${e(x.text)} <small>${e(x.evidence_ids.join(' · '))}</small></li>`).join('')}</ol><small>${L('AI-selected sequence of validated statements','AI 选择顺序，内容经约束验证','Urutan dipilih AI bagi pernyataan disahkan')}</small>`:''}</section>`;}
function roleDetail(a,r,marketRegion=a.context.region){const facts=(r.marketByRegion&&r.marketByRegion[marketRegion])||r.marketFacts||[];return `<section class="an-role-detail"><div class="an-role-title"><span class="an-eyebrow">${L('EXPLORE THE WORK','了解具体工作','TEROKAI TUGAS')}</span><h2>${e(P(r.title))}</h2>${sourceLink(r.source)}</div><div class="an-role-grid"><div><h3>${L('Your connection','与你的关联','Kaitan dengan anda')}</h3><p>${L('Interest','兴趣','Minat')}: ${r.interest.value===null?label('unknown'):r.interest.value>=5?label('high'):r.interest.value<=3?label('low'):label('neutral')}</p><p>${L('Reported practice','自述实践','Amalan dilaporkan')}: ${label(r.readiness.status)}</p>${evidence(a,Object.keys(r.interestWeights).concat(Object.keys(r.preferenceWeights),r.readiness.evidenceIds))}<details><summary>${L('Why this exploration order?','为什么这样排列？','Mengapa urutan ini?')}</summary><p>${L('Task association uses interest (three parts) and work preference (one part). Within each pair, the task emphasis below applies. Missing values prevent ordering; a difference below 0.35 points is a tie.','任务关联采用兴趣三份、工作偏好一份；每组按下列任务权重计算。缺失回答时不排序，差值小于 0.35 点时并列。','Perkaitan tugas menggunakan tiga bahagian minat dan satu bahagian keutamaan kerja. Wajaran tugas di bawah digunakan. Nilai hilang menghalang susunan; beza bawah 0.35 mata ialah seri.')}</p><code>${e(JSON.stringify({interest:r.interest.terms,preference:r.preference.terms}))}</code><p>${L('Product heuristic on ordinal responses, not a probability or a validated competence measure.','基于顺序量表回答的产品启发式，不是概率或经过验证的能力测量。','Heuristik produk atas jawapan ordinal, bukan kebarangkalian atau ukuran kemahiran disahkan.')}</p></details></div><div><h3>${L('A practical task to try','可尝试的实践任务','Tugas praktikal untuk dicuba')}</h3><p>${e(P(r.project))}</p><p>${L('AI can draft or organise material for this task. Independently check accuracy, context and responsibility; this is a task-based hypothesis, not a job-loss prediction.','AI 可辅助起草或整理这类任务材料。需独立核查准确性、情境和责任；这是任务层面的假设，不是失业预测。','AI boleh mendraf atau menyusun bahan tugas ini. Semak ketepatan, konteks dan tanggungjawab secara bebas; ini hipotesis tugas, bukan ramalan kehilangan kerja.')}</p>${button(L('Explore this in What If','进入 What If 探索','Terokai dalam What If'),'plan:'+r.id)}</div></div>${renderCareerStudy(a,r)}${renderAIImpact(r)}${renderTrendSources(a,r)}<h3>${L('Requirements still to verify','仍需核验的要求','Keperluan yang perlu disahkan')}</h3><p>${L('These official requirements are not measured gaps. No answer here verifies a professional skill.','这些官方要求不等于已测量的个人差距。这里没有任何回答验证了专业技能。','Keperluan rasmi ini bukan jurang diukur. Tiada jawapan mengesahkan kemahiran profesional.')}</p><div class="an-requirements">${r.requirements.map(s=>`<div><strong lang="en">${e(s.label)}</strong><span>${label('unknown')}</span></div>`).join('')||`<p>${L('Detailed skill data unavailable.','详细技能数据暂无。','Data kemahiran terperinci tiada.')}</p>`}</div>${renderFutureSkills(a,r)}<details class="an-source"><summary>${L('Official tasks, entry context & source scope','官方任务、准入背景与来源范围','Tugas rasmi, konteks kemasukan dan skop sumber')}</summary>${r.source?`<p lang="en">${e(r.source.description)}</p><ul lang="en">${r.tasks.slice(0,5).map(t=>`<li>${e(t.label)}</li>`).join('')}</ul><p lang="en">${e(r.source.education.map(t=>t.label).join(' '))}</p><p>${e(r.source.version)} · US · ${e(r.source.verified_at)}</p><p>${L('Checked date, not publication date. US occupational context does not establish Malaysian licensing or hiring requirements. This is a related occupational context, not exact equivalence with every local job title.','以上为核查时间，不是发布日期。美国职业背景不能确立马来西亚资格或招聘要求。这是相关职业背景，不代表与各地职位名称完全等价。','Tarikh semakan, bukan tarikh terbit. Konteks pekerjaan AS tidak menentukan lesen atau syarat pengambilan Malaysia. Ini konteks berkaitan, bukan kesetaraan tepat semua jawatan tempatan.')}</p>${sourceLink(r.source)}`:`<p>${L('Official source unavailable; the task is an explicitly labelled team exercise.','官方来源暂缺；任务为明确标注的团队练习。','Sumber rasmi tidak tersedia; tugas ialah latihan pasukan berlabel.')}</p>`}</details><h3>${L('Market context','市场背景','Konteks pasaran')} · ${e(marketRegion)}</h3><div class="an-region-switch" role="group" aria-label="${L('Market region','市场地区','Wilayah pasaran')}">${['MY','US','GLOBAL'].map(reg=>`<button type="button" class="${reg===marketRegion?'active':''}" data-combined-action="region:${reg}">${L(...REGION_LABEL[reg])}</button>`).join('')}</div><p>${facts.length?L('Dated role context is available below; it is not a personal forecast.','下方有该职业的有日期背景；不是个人预测。','Konteks peranan bertarikh tersedia; bukan ramalan peribadi.'):L('No comparable role-specific market statistic is available in this snapshot for your selected market. Use the official tasks to investigate local roles; no salary or growth is inferred.','当前快照没有所选市场中该职业的可比专属统计。可依据官方任务核查本地岗位；不推断薪资或增长。','Tiada statistik pasaran khusus peranan yang setanding untuk pasaran dipilih. Gunakan tugas rasmi untuk menyiasat jawatan tempatan; tiada gaji atau pertumbuhan disimpulkan.')}</p>${facts.map(f=>`<details><summary>${e(f.source_name)} · ${e(f.reference_period)}</summary><p>${e(String(f.value))} ${e(f.unit||'')}</p><p>${e(f.granularity)} · ${e(f.mapping_status)}</p><a href="${e(f.source_url)}" target="_blank" rel="noopener noreferrer">${L('Source','来源','Sumber')} ↗</a></details>`).join('')}</section>`;}
export function galaxy(model,options={},section='map'){const a=model.assessment,r=a.roles[(options.path==='B'?1:0)]||a.roles[0];const marketRegion=['MY','US','GLOBAL'].includes(options.region)?options.region:a.context.region;const tabs=[['paths',L('Routes','路线','Laluan')],['map',L('Explore','探索','Terokai')],['compare',L('Compare','比较','Banding')],['skills',L('Skill tree','技能树','Pokok kemahiran')]].map(([id,name])=>button(name,'section:'+id,section===id?'button primary':'button secondary')).join('');let body;if(section==='skills'){body=renderSkillDna(a,options);}else if(['compare','paths'].includes(section)){body=`<div class="an-comparison">${a.roles.map(x=>`<article><h2>${e(P(x.title))}</h2><p>${L('Exploration priority','探索优先级','Keutamaan penerokaan')} ${x.priority}</p><p>${L('Interest evidence','兴趣依据','Bukti minat')}: ${x.interest.value===null?label('unknown'):x.interest.value>=5?label('high'):x.interest.value<=3?label('low'):label('neutral')}</p><p>${L('Current readiness','当前准备度','Kesediaan semasa')}: ${label(x.readiness.status)}</p><p>${L('Unverified requirements','未验证要求','Keperluan belum disahkan')}: ${x.requirements.length}</p><p>${e(P(x.project))}</p>${evidence(a,Object.keys(x.interestWeights))}${button(L('Try this route','尝试此路线','Cuba laluan ini'),'plan:'+x.id)}</article>`).join('')}</div>`;}else{body=`<p class="an-map-key">${L('Nodes are occupational routes; selection opens details. Position, distance and line length do not encode suitability. The connecting lines show routes available from your selected direction.','节点代表职业路线，选择后显示详情。位置、距离和线长不表示适合度；连线表示所选方向可探索的路线。','Nod ialah laluan pekerjaan; pilihan membuka butiran. Kedudukan, jarak dan panjang garis tidak menunjukkan kesesuaian. Garis menunjukkan laluan daripada arah dipilih.')}</p>${renderCareerStarMap(model.report,options.path||'A')}${roleDetail(a,r,marketRegion)}`;}return `<div class="an-view an-galaxy" data-rebuild="galaxy">${header(3,L('CAREER GALAXY','职业星系','GALAKSI KERJAYA'),L('Find work worth<br>exploring.','发现值得<br>探索的工作。','Temui tugas yang<br>wajar diterokai.'),a.tied?L('Your evidence does not justify a clear first choice. Both routes are open experiments.','现有证据不足以明确优先顺序，两条路线均值得通过实践探索。','Bukti belum menentukan pilihan pertama. Kedua-dua laluan terbuka untuk diuji.'):L('The first route has stronger task-preference evidence. This is an exploration order, not a prediction of success.','第一条路线具有更强的任务偏好依据。这是探索顺序，不是成功预测。','Laluan pertama mempunyai bukti keutamaan tugas lebih kuat. Ini urutan penerokaan, bukan ramalan kejayaan.'))}<nav data-galaxy-section="${e(section)}" class="an-tabs" aria-label="${L('Career views','职业视图','Paparan kerjaya')}">${tabs}</nav>${body}${methodology(a)}</div>`;}
function planList(s){return `<ol class="an-timeline">${s.stages.map(x=>`<li><span class="an-step-dot"></span><div><small>${L('PLANNED','计划','DIRANCANG')} · ${x.hours} h · ${x.endWeek===null?L('No time allocated','未分配时间','Tiada masa diperuntukkan'):L('By week','计划至第','Menjelang minggu')+' '+x.endWeek}</small><h3>${e(P(x.title))}</h3><p>${e(P(x.task))}</p><p class="an-check">${L('Review','验收','Semakan')}: ${e(P(x.check))}</p></div></li>`).join('')}</ol>`;}
export function whatif(model,options={}){const a=model.assessment,s=simulate(a,options.assumptions),base=simulate(a,{targetCareer:s.roleId}),r=a.roles.find(r=>r.id===s.roleId);const select=(key,title,values,selected)=>`<label>${title}<select data-v2-control="${key}">${values.map(([v,t])=>`<option value="${e(v)}" ${String(v)===String(selected)?'selected':''}>${e(t)}</option>`).join('')}</select></label>`;return `<div class="an-view an-whatif" data-rebuild="whatif">${header(4,L('YOUR FUTURE LAB','未来情景实验室','MAKMAL MASA DEPAN'),L('Change the plan.<br>Keep the evidence.','调整计划，<br>保留事实。','Ubah rancangan.<br>Kekalkan bukti.'),L('Explore what you could practise, in what order, and with what checks. Time creates room for learning; it does not prove skill.','探索可以练习什么、先后顺序及如何验收。时间为学习提供空间，但不能证明能力。','Terokai latihan, urutan dan semakannya. Masa memberi ruang untuk belajar, bukan membuktikan kemahiran.'))}<section class="an-controls">${select('targetCareer',L('Target career','目标职业','Kerjaya sasaran'),a.roles.map(r=>[r.id,P(r.title)]),s.roleId)}${select('focusSkill',L('Practice priority','练习重点','Keutamaan latihan'),[['foundations',L('Prerequisites','先修基础','Prasyarat')],['practice',L('Task sample','任务样本','Sampel tugas')],['verification',L('Verification','核验','Pengesahan')],['portfolio',L('Portfolio case','作品案例','Kes portfolio')],...r.requirements.map(x=>[x.id,x.label])],s.focusSelection)}<label>${L('Hours per week','每周小时','Jam seminggu')}<input type="number" data-v2-control="planHours" min="0" max="40" step="0.5" value="${s.weeklyHours}"></label>${select('skillEvidence',L('Starting evidence (assumption)','起点证据（假设）','Bukti permulaan (andaian)'),[['baseline',L('Keep my reported starting point','保持自述起点','Kekalkan titik permulaan dilaporkan')],['practiced',L('Assume this task sample was reviewed','假设此任务样本已复核','Andaikan sampel tugas ini disemak')]],s.assumedEvidence?'practiced':'baseline')}</section><p>${s.budgetAssumed?L('Five hours is a planning default, not a time commitment you reported.','五小时是规划默认值，不是你自述的时间承诺。','Lima jam ialah nilai perancangan lalai, bukan komitmen dilaporkan.'):L('Your selected budget applies only to this scenario.','所选预算只用于本情景。','Bajet dipilih hanya digunakan dalam senario ini.')}</p><div class="an-horizons">${s.horizons.map((h,i)=>`<article><span class="an-eyebrow">${[L('2 MONTHS','2 个月','2 BULAN'),L('1 YEAR','1 年','1 TAHUN'),L('2 YEARS','2 年','2 TAHUN')][i]}</span><h2>${[L('Explore & validate','探索与验证','Terokai & sahkan'),L('Build practice','积累实践','Bina amalan'),L('Review readiness','复核准备度','Semak kesediaan')][i]}</h2><strong>${h.budgetHours} h</strong><p>${h.planned.length} / 4 ${L('planned milestones fit the budget','个计划里程碑可纳入预算','pencapaian dirancang muat dalam bajet')}</p><small>${h.unallocatedHours>0?L('Remaining time needs a new plan after reviewing the first sample. No automatic progress is inferred.','剩余时间需在首个样本复核后重新规划，不推断自动进步。','Baki masa memerlukan pelan baharu selepas sampel pertama disemak. Tiada kemajuan automatik disimpulkan.'):L('Incomplete steps remain next in the prerequisite order.','未完成步骤继续按先修顺序安排。','Langkah belum siap mengikut urutan prasyarat.')}</small></article>`).join('')}</div><h2>${e(P(r.title))}</h2>${planList(s)}<section class="an-compare-plan"><h2>${L('Compare with the baseline plan','与基础计划比较','Banding dengan pelan asas')}</h2><div class="an-comparison"><article><h3>${L('Baseline','基础计划','Asas')}</h3><p>${base.totalHours} h · ${base.weeklyHours} ${L('h/week','小时／周','jam/minggu')}</p><p>${L('Final review week','最终复核计划周','Minggu semakan akhir')}: ${base.stages.at(-1).endWeek??'—'}</p></article><article><h3>${L('This scenario','本次情景','Senario ini')}</h3><p>${s.totalHours} h · ${s.weeklyHours} ${L('h/week','小时／周','jam/minggu')}</p><p>${L('Final review week','最终复核计划周','Minggu semakan akhir')}: ${s.stages.at(-1).endWeek??'—'}</p></article></div><p>${L('Effort estimates are team planning assumptions, not official training durations. A reviewed sample assumption shortens preparation; it never marks occupational skills as verified. All occupational requirements still need separate evidence.','工时是团队规划估计，不是官方培训时长。已复核样本的假设可缩短准备，但不会把职业技能标为已验证。职业要求仍需独立证据。','Anggaran usaha ialah andaian pasukan, bukan tempoh latihan rasmi. Andaian sampel disemak memendekkan persediaan tetapi tidak mengesahkan kemahiran pekerjaan. Semua keperluan masih memerlukan bukti berasingan.')}</p>${button(L('Reset scenario','重置情景','Tetapkan semula senario'),'v2-reset','text-button')}${changesNote(s)}</section>${methodology(a)}</div>`;}
function renderTrendSources(a,r){const src=r.source;const facts=[];if(r.marketByRegion){for(const reg of ['US','GLOBAL','MY'])facts.push(...(r.marketByRegion[reg]||[]));}return `<details class="an-trend-sources"><summary>${L('Trend sources for this role','此职业的趋势来源','Sumber trend untuk peranan ini')}</summary><ul>${src?`<li><a target="_blank" rel="noopener noreferrer" href="${e(src.url)}">O*NET · ${e(r.sourceId)}</a> <small>US · ${e(src.version)} · ${e(src.verified_at)}</small></li>`:''}${facts.slice(0,5).map(f=>`<li><a target="_blank" rel="noopener noreferrer" href="${e(f.source_url)}">${e(f.source_name)}</a> <small>${e(f.region)} · ${e(f.reference_period)}</small><p>${e(f.granularity)} · ${e(f.mapping_status)}</p></li>`).join('')}</ul><p>${L('Dated occupational context with source, region and reference period. Nothing here is presented as a real-time feed.','有日期、来源、地区与参考周期的职业背景。此处不伪装为实时数据。','Konteks pekerjaan bertarikh dengan sumber, wilayah dan tempoh rujukan. Tiada yang dibentangkan sebagai suapan masa nyata.')}</p></details>`;}
function renderFutureSkills(a,r){const axes=futureSkillAxes(r.requirements||[]);const max=Math.max(1,...axes.map(x=>x.count));const cx=170,cy=150,radius=105;const pt=(axis,i)=>{const ang=(-90+i*90)*Math.PI/180;const val=axis.count/max;return [cx+Math.cos(ang)*radius*val,cy+Math.sin(ang)*radius*val];};const polygon=axes.map((axis,i)=>pt(axis,i).map(n=>n.toFixed(1)).join(',')).join(' ');const spokes=axes.map((axis,i)=>{const ang=(-90+i*90)*Math.PI/180;const ex=cx+Math.cos(ang)*radius,ey=cy+Math.sin(ang)*radius;return `<line x1="${cx}" y1="${cy}" x2="${ex.toFixed(1)}" y2="${ey.toFixed(1)}"/>`;}).join('');const labels=axes.map((axis,i)=>{const ang=(-90+i*90)*Math.PI/180;const lx=cx+Math.cos(ang)*(radius+34),ly=cy+Math.sin(ang)*(radius+28);const anchor=Math.abs(Math.cos(ang))<0.2?'middle':Math.cos(ang)>0?'start':'end';return `<text x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="${anchor}">${e(L(...axis.label))}</text>`;}).join('');const dots=axes.map((axis,i)=>{const [x,y]=pt(axis,i);return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="4"/>`;}).join('');const rising=[...new Set(axes.filter(a=>a.id==='technical'||a.id==='aiData').flatMap(a=>a.skills))].slice(0,5);return `<details class="an-future-skills" open><summary>${L('Future skills radar','未来技能雷达','Radar kemahiran masa depan')}</summary><div class="an-radar-wrap"><svg class="an-radar" viewBox="0 0 340 300" role="img" aria-label="${L('Future skill emphasis by dimension','按维度展示的未来技能侧重','Penekanan kemahiran masa depan mengikut dimensi')}"><g class="an-radar-grid">${spokes}</g><polygon class="an-radar-shape" points="${polygon}"/><g class="an-radar-dots">${dots}</g><g class="an-radar-labels">${labels}</g></svg><p class="an-radar-note">${L('Axes show how the official requirements concentrate across dimensions, not your current proficiency.','坐标轴展示官方要求在各维度的分布，不是你的当前熟练度。','Paksi menunjukkan tumpuan keperluan rasmi mengikut dimensi, bukan kecekapan semasa anda.')}</p></div>${rising.length?`<p><strong>${L('Skills likely to matter more','可能更重要的技能','Kemahiran yang mungkin lebih penting')}</strong> ${rising.map(x=>`<span lang="en">${e(x)}</span>`).join(' · ')}</p>`:''}<p>${L('Your reported practice is separate: it does not pre-fill any of these future requirements.','你的自述实践另计，不会预先填满这些未来要求。','Amalan dilaporkan anda dikira berasingan dan tidak mengisi keperluan masa depan ini.')}</p></details>`;}
function renderSourceSnapshot(a){return `<section class="an-source-snapshot"><h3>${L('Source snapshot & study notes','来源快照与研究说明','Snapshot sumber & nota kajian')}</h3><dl><div><dt>${L('Occupational data','职业数据','Data pekerjaan')}</dt><dd>${e(a.knowledgeVersion)} · ${L('20 O*NET occupations + ESCO skill relations','20 个 O*NET 职业 + ESCO 技能关联','20 pekerjaan O*NET + hubungan kemahiran ESCO')}</dd></div><div><dt>${L('Regional data','地区数据','Data wilayah')}</dt><dd>${e(a.regionalVersion)} · US / GLOBAL / MY</dd></div><div><dt>${L('Mapping rules','映射规则','Peraturan pemetaan')}</dt><dd>${e(a.mappingVersion)} · ${e(a.version)}</dd></div><div><dt>${L('Report','报告','Laporan')}</dt><dd>${e(a.id)} · ${e(a.generatedAt||L('Current session','当前会话','Sesi semasa'))}</dd></div></dl><ul><li>${L('Official facts','官方事实','Fakta rasmi')}: ${L('occupational tasks, skills, education and dated regional context.','职业任务、技能、教育与有日期的地区背景。','tugas, kemahiran, pendidikan dan konteks wilayah bertarikh.')}</li><li>${L('Team inference','团队推断','Inferens pasukan')}: ${L('task grouping, skill axes, value shift and exploration order.','任务分组、技能轴、价值转移与探索顺序。','pengelasan tugas, paksi kemahiran, perubahan nilai dan urutan penerokaan.')}</li><li>${L('Data coverage gaps','数据覆盖不足','Kekangan liputan data')}: ${L('Malaysia market facts cover only software and AI research roles; other roles show no comparable statistic.','马来西亚市场事实仅覆盖软件与 AI 研究角色；其他角色无可比统计。','Fakta pasaran Malaysia hanya meliputi peranan perisian dan penyelidikan AI; peranan lain tiada statistik setanding.')}</li></ul><p>${L('This is a verified snapshot, not a real-time feed.','这是经核查的快照，不是实时数据流。','Ini snapshot disahkan, bukan suapan masa nyata.')}</p></section>`;}
